insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_true_false_not_given','reading',1,'{"skill":"reading_true_false_not_given","module":"reading","title":"False or Not Given?","outcome":"Separate contradiction from missing information.","trap":"Do not treat a missing detail as false.","strategy":"Check each part of the statement. Find support or a contradiction. If neither exists, choose Not Given.","example":"The shop opens at nine. → It opens at ten: False. It closes at six: Not Given.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_true_false_not_given-0","kind":"choice","prompt":"The library closes later than before.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: The library now closes at eight instead of six.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six.","evidence":["The library now closes at eight instead of six.","Information absent"],"evidence_answer":"The library now closes at eight instead of six.","stage":"guided"},{"id":"reading_true_false_not_given-1","kind":"choice","prompt":"All diesel buses were replaced.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: Electric buses replaced half the diesel fleet last year.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year.","evidence":["Electric buses replaced half the diesel fleet last year.","Information absent"],"evidence_answer":"Electric buses replaced half the diesel fleet last year.","stage":"guided"},{"id":"reading_true_false_not_given-2","kind":"choice","prompt":"Online tickets cost less than tickets at the door.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online.","evidence":["Museum visitors can book tickets online.","Information absent"],"evidence_answer":"Information absent","stage":"guided"},{"id":"reading_true_false_not_given-3","kind":"choice","prompt":"Volunteers meet every Saturday.","options":["True","False","Not Given"],"answer":"False","explanation":"The passage contradicts the statement: Volunteers meet in the garden every second Saturday.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday.","evidence":["Volunteers meet in the garden every second Saturday.","Information absent"],"evidence_answer":"Volunteers meet in the garden every second Saturday.","stage":"guided"},{"id":"reading_true_false_not_given-4","kind":"choice","prompt":"The course begins in May.","options":["False","Not Given","True"],"answer":"True","explanation":"The passage supports the statement: The evening course runs for six weeks and starts in May.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May.","evidence":["The evening course runs for six weeks and starts in May.","Information absent"],"evidence_answer":"The evening course runs for six weeks and starts in May.","stage":"independent"},{"id":"reading_true_false_not_given-5","kind":"choice","prompt":"The pool offers swimming lessons.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning.","evidence":["The pool is closed on Mondays for cleaning.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-6","kind":"choice","prompt":"Cycling to work increased after the lane opened.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: More residents cycled to work after a protected lane opened.","hint":"Compare every detail with the lesson strategy.","passage":"More residents cycled to work after a protected lane opened.","evidence":["More residents cycled to work after a protected lane opened.","Information absent"],"evidence_answer":"More residents cycled to work after a protected lane opened.","stage":"independent"},{"id":"reading_true_false_not_given-7","kind":"choice","prompt":"The market moved because it needed more customers.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: The market moved indoors because rain damaged the stalls.","hint":"Compare every detail with the lesson strategy.","passage":"The market moved indoors because rain damaged the stalls.","evidence":["The market moved indoors because rain damaged the stalls.","Information absent"],"evidence_answer":"The market moved indoors because rain damaged the stalls.","stage":"independent"},{"id":"reading_true_false_not_given-8","kind":"choice","prompt":"The cafe sells organic coffee.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The cafe buys its coffee from two local suppliers.","evidence":["The cafe buys its coffee from two local suppliers.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-9","kind":"choice","prompt":"Passengers wait less time between trains.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: The new timetable reduced the wait between trains from fifteen to ten minutes.","hint":"Compare every detail with the lesson strategy.","passage":"The new timetable reduced the wait between trains from fifteen to ten minutes.","evidence":["The new timetable reduced the wait between trains from fifteen to ten minutes.","Information absent"],"evidence_answer":"The new timetable reduced the wait between trains from fifteen to ten minutes.","stage":"independent"},{"id":"reading_true_false_not_given-10","kind":"choice","prompt":"Students may borrow three books at once.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: Students may borrow two books at a time.","hint":"Compare every detail with the lesson strategy.","passage":"Students may borrow two books at a time.","evidence":["Students may borrow two books at a time.","Information absent"],"evidence_answer":"Students may borrow two books at a time.","stage":"independent"},{"id":"reading_true_false_not_given-11","kind":"choice","prompt":"The trail is suitable for wheelchairs.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The park has a new walking trail around the lake.","evidence":["The park has a new walking trail around the lake.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-12","kind":"choice","prompt":"Labelled bins were followed by increased paper separation.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: Households separated more paper after receiving labelled bins.","hint":"Compare every detail with the lesson strategy.","passage":"Households separated more paper after receiving labelled bins.","evidence":["Households separated more paper after receiving labelled bins.","Information absent"],"evidence_answer":"Households separated more paper after receiving labelled bins.","stage":"independent"},{"id":"reading_true_false_not_given-13","kind":"choice","prompt":"Tickets can be collected on Friday afternoon.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: Tickets must be collected before noon on Friday.","hint":"Compare every detail with the lesson strategy.","passage":"Tickets must be collected before noon on Friday.","evidence":["Tickets must be collected before noon on Friday.","Information absent"],"evidence_answer":"Tickets must be collected before noon on Friday.","stage":"independent"},{"id":"reading_true_false_not_given-14","kind":"choice","prompt":"The bakery opens at seven on Sundays.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The bakery opens at seven on weekdays.","evidence":["The bakery opens at seven on weekdays.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-15","kind":"choice","prompt":"Working from home reduced commuting time.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: Staff saved travel time by working from home twice a week.","hint":"Compare every detail with the lesson strategy.","passage":"Staff saved travel time by working from home twice a week.","evidence":["Staff saved travel time by working from home twice a week.","Information absent"],"evidence_answer":"Staff saved travel time by working from home twice a week.","stage":"independent"},{"id":"reading_true_false_not_given-16","kind":"choice","prompt":"The tour visits the harbour.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: The walking tour includes the castle but not the harbour.","hint":"Compare every detail with the lesson strategy.","passage":"The walking tour includes the castle but not the harbour.","evidence":["The walking tour includes the castle but not the harbour.","Information absent"],"evidence_answer":"The walking tour includes the castle but not the harbour.","stage":"independent"},{"id":"reading_true_false_not_given-17","kind":"choice","prompt":"Website appointments are confirmed immediately.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"Patients can request appointments by phone or through the website.","evidence":["Patients can request appointments by phone or through the website.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-18","kind":"choice","prompt":"Repairing leaks was followed by lower water use.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: Water use fell after leaking pipes were repaired.","hint":"Compare every detail with the lesson strategy.","passage":"Water use fell after leaking pipes were repaired.","evidence":["Water use fell after leaking pipes were repaired.","Information absent"],"evidence_answer":"Water use fell after leaking pipes were repaired.","stage":"independent"},{"id":"reading_true_false_not_given-19","kind":"choice","prompt":"Lunch is included in the fee.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: The workshop fee covers materials but excludes lunch.","hint":"Compare every detail with the lesson strategy.","passage":"The workshop fee covers materials but excludes lunch.","evidence":["The workshop fee covers materials but excludes lunch.","Information absent"],"evidence_answer":"The workshop fee covers materials but excludes lunch.","stage":"independent"},{"id":"reading_true_false_not_given-20","kind":"choice","prompt":"The waiting room is heated.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"A waiting room was added beside platform two.","evidence":["A waiting room was added beside platform two.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-21","kind":"choice","prompt":"Farmers wanted to rely less on a single crop.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: Farmers planted more varieties to reduce dependence on one crop.","hint":"Compare every detail with the lesson strategy.","passage":"Farmers planted more varieties to reduce dependence on one crop.","evidence":["Farmers planted more varieties to reduce dependence on one crop.","Information absent"],"evidence_answer":"Farmers planted more varieties to reduce dependence on one crop.","stage":"independent"},{"id":"reading_true_false_not_given-22","kind":"choice","prompt":"The festival is in August.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: The festival takes place in September, not August as first announced.","hint":"Compare every detail with the lesson strategy.","passage":"The festival takes place in September, not August as first announced.","evidence":["The festival takes place in September, not August as first announced.","Information absent"],"evidence_answer":"The festival takes place in September, not August as first announced.","stage":"independent"},{"id":"reading_true_false_not_given-23","kind":"choice","prompt":"The paintings are available to buy.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The gallery displays paintings by regional artists.","evidence":["The gallery displays paintings by regional artists.","Information absent"],"evidence_answer":"Information absent","stage":"independent"}]}'::jsonb,true) on conflict(skill,version) do nothing;
insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_paraphrase_matching','reading',1,'{"skill":"reading_paraphrase_matching","module":"reading","title":"Recognise the same meaning","outcome":"Match meaning even when the wording changes.","trap":"A shared word does not guarantee a shared meaning.","strategy":"Compare who, what, quantity and time. Reject an option that adds or reverses a detail.","example":"Reduced waiting time means a shorter wait, not a shorter journey.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_paraphrase_matching-0","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["extended opening hours","the complete closure of the library","an increase in prices at the library"],"answer":"extended opening hours","explanation":"“extended opening hours” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six.","stage":"guided"},{"id":"reading_paraphrase_matching-1","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the buses","an increase in prices at the buses","partial fleet replacement"],"answer":"partial fleet replacement","explanation":"“partial fleet replacement” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year.","stage":"guided"},{"id":"reading_paraphrase_matching-2","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the museum","online booking availability","the complete closure of the museum"],"answer":"online booking availability","explanation":"“online booking availability” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online.","stage":"guided"},{"id":"reading_paraphrase_matching-3","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["a fortnightly meeting","the complete closure of the garden","an increase in prices at the garden"],"answer":"a fortnightly meeting","explanation":"“a fortnightly meeting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday.","stage":"guided"},{"id":"reading_paraphrase_matching-4","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the course","an increase in prices at the course","a six-week evening course"],"answer":"a six-week evening course","explanation":"“a six-week evening course” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May.","stage":"independent"},{"id":"reading_paraphrase_matching-5","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the pool","a weekly maintenance closure","the complete closure of the pool"],"answer":"a weekly maintenance closure","explanation":"“a weekly maintenance closure” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning.","stage":"independent"},{"id":"reading_paraphrase_matching-6","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["growth in cycle commuting","the complete closure of the bicycles","an increase in prices at the bicycles"],"answer":"growth in cycle commuting","explanation":"“growth in cycle commuting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"More residents cycled to work after a protected lane opened.","stage":"independent"},{"id":"reading_paraphrase_matching-7","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the market","an increase in prices at the market","relocation after weather damage"],"answer":"relocation after weather damage","explanation":"“relocation after weather damage” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The market moved indoors because rain damaged the stalls.","stage":"independent"},{"id":"reading_paraphrase_matching-8","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the cafe","local coffee purchasing","the complete closure of the cafe"],"answer":"local coffee purchasing","explanation":"“local coffee purchasing” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The cafe buys its coffee from two local suppliers.","stage":"independent"},{"id":"reading_paraphrase_matching-9","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["more frequent trains","the complete closure of the trains","an increase in prices at the trains"],"answer":"more frequent trains","explanation":"“more frequent trains” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The new timetable reduced the wait between trains from fifteen to ten minutes.","stage":"independent"},{"id":"reading_paraphrase_matching-10","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the school","an increase in prices at the school","a borrowing limit"],"answer":"a borrowing limit","explanation":"“a borrowing limit” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Students may borrow two books at a time.","stage":"independent"},{"id":"reading_paraphrase_matching-11","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the park","a new lakeside path","the complete closure of the park"],"answer":"a new lakeside path","explanation":"“a new lakeside path” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The park has a new walking trail around the lake.","stage":"independent"},{"id":"reading_paraphrase_matching-12","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["improved paper recycling","the complete closure of the recycling","an increase in prices at the recycling"],"answer":"improved paper recycling","explanation":"“improved paper recycling” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Households separated more paper after receiving labelled bins.","stage":"independent"},{"id":"reading_paraphrase_matching-13","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the concert","an increase in prices at the concert","a ticket collection deadline"],"answer":"a ticket collection deadline","explanation":"“a ticket collection deadline” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Tickets must be collected before noon on Friday.","stage":"independent"},{"id":"reading_paraphrase_matching-14","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the bakery","weekday opening times","the complete closure of the bakery"],"answer":"weekday opening times","explanation":"“weekday opening times” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The bakery opens at seven on weekdays.","stage":"independent"},{"id":"reading_paraphrase_matching-15","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["less time commuting","the complete closure of the office","an increase in prices at the office"],"answer":"less time commuting","explanation":"“less time commuting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Staff saved travel time by working from home twice a week.","stage":"independent"},{"id":"reading_paraphrase_matching-16","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the tour","an increase in prices at the tour","a limited tour route"],"answer":"a limited tour route","explanation":"“a limited tour route” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The walking tour includes the castle but not the harbour.","stage":"independent"},{"id":"reading_paraphrase_matching-17","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the clinic","two booking methods","the complete closure of the clinic"],"answer":"two booking methods","explanation":"“two booking methods” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Patients can request appointments by phone or through the website.","stage":"independent"},{"id":"reading_paraphrase_matching-18","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["reduced water consumption","the complete closure of the water","an increase in prices at the water"],"answer":"reduced water consumption","explanation":"“reduced water consumption” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Water use fell after leaking pipes were repaired.","stage":"independent"},{"id":"reading_paraphrase_matching-19","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the workshop","an increase in prices at the workshop","what the fee includes"],"answer":"what the fee includes","explanation":"“what the fee includes” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The workshop fee covers materials but excludes lunch.","stage":"independent"},{"id":"reading_paraphrase_matching-20","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the station","a new waiting facility","the complete closure of the station"],"answer":"a new waiting facility","explanation":"“a new waiting facility” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"A waiting room was added beside platform two.","stage":"independent"},{"id":"reading_paraphrase_matching-21","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["diversification of crops","the complete closure of the orchard","an increase in prices at the orchard"],"answer":"diversification of crops","explanation":"“diversification of crops” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Farmers planted more varieties to reduce dependence on one crop.","stage":"independent"},{"id":"reading_paraphrase_matching-22","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the festival","an increase in prices at the festival","a revised festival date"],"answer":"a revised festival date","explanation":"“a revised festival date” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The festival takes place in September, not August as first announced.","stage":"independent"},{"id":"reading_paraphrase_matching-23","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the gallery","an exhibition of regional art","the complete closure of the gallery"],"answer":"an exhibition of regional art","explanation":"“an exhibition of regional art” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The gallery displays paintings by regional artists.","stage":"independent"}]}'::jsonb,true) on conflict(skill,version) do nothing;
insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_matching_headings','reading',1,'{"skill":"reading_matching_headings","module":"reading","title":"Find the main idea","outcome":"Choose a heading covering the whole paragraph.","trap":"An example can distract from the main point.","strategy":"Summarise the paragraph in a few words, then compare the breadth of each heading.","example":"A paragraph explaining a move caused by flooding needs a heading about relocation, not ticket prices.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_matching_headings-0","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["extended opening hours","The history of ticket prices","Plans for overseas expansion"],"answer":"extended opening hours","explanation":"The paragraph focuses on extended opening hours. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-1","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","partial fleet replacement"],"answer":"partial fleet replacement","explanation":"The paragraph focuses on partial fleet replacement. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-2","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","online booking availability","The history of ticket prices"],"answer":"online booking availability","explanation":"The paragraph focuses on online booking availability. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-3","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["a fortnightly meeting","The history of ticket prices","Plans for overseas expansion"],"answer":"a fortnightly meeting","explanation":"The paragraph focuses on a fortnightly meeting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-4","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a six-week evening course"],"answer":"a six-week evening course","explanation":"The paragraph focuses on a six-week evening course. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-5","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","a weekly maintenance closure","The history of ticket prices"],"answer":"a weekly maintenance closure","explanation":"The paragraph focuses on a weekly maintenance closure. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-6","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["growth in cycle commuting","The history of ticket prices","Plans for overseas expansion"],"answer":"growth in cycle commuting","explanation":"The paragraph focuses on growth in cycle commuting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"More residents cycled to work after a protected lane opened. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-7","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","relocation after weather damage"],"answer":"relocation after weather damage","explanation":"The paragraph focuses on relocation after weather damage. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The market moved indoors because rain damaged the stalls. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-8","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","local coffee purchasing","The history of ticket prices"],"answer":"local coffee purchasing","explanation":"The paragraph focuses on local coffee purchasing. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The cafe buys its coffee from two local suppliers. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-9","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["more frequent trains","The history of ticket prices","Plans for overseas expansion"],"answer":"more frequent trains","explanation":"The paragraph focuses on more frequent trains. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The new timetable reduced the wait between trains from fifteen to ten minutes. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-10","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a borrowing limit"],"answer":"a borrowing limit","explanation":"The paragraph focuses on a borrowing limit. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Students may borrow two books at a time. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-11","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","a new lakeside path","The history of ticket prices"],"answer":"a new lakeside path","explanation":"The paragraph focuses on a new lakeside path. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The park has a new walking trail around the lake. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-12","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["improved paper recycling","The history of ticket prices","Plans for overseas expansion"],"answer":"improved paper recycling","explanation":"The paragraph focuses on improved paper recycling. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Households separated more paper after receiving labelled bins. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-13","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a ticket collection deadline"],"answer":"a ticket collection deadline","explanation":"The paragraph focuses on a ticket collection deadline. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Tickets must be collected before noon on Friday. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-14","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","weekday opening times","The history of ticket prices"],"answer":"weekday opening times","explanation":"The paragraph focuses on weekday opening times. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The bakery opens at seven on weekdays. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-15","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["less time commuting","The history of ticket prices","Plans for overseas expansion"],"answer":"less time commuting","explanation":"The paragraph focuses on less time commuting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Staff saved travel time by working from home twice a week. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-16","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a limited tour route"],"answer":"a limited tour route","explanation":"The paragraph focuses on a limited tour route. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The walking tour includes the castle but not the harbour. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-17","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","two booking methods","The history of ticket prices"],"answer":"two booking methods","explanation":"The paragraph focuses on two booking methods. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Patients can request appointments by phone or through the website. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-18","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["reduced water consumption","The history of ticket prices","Plans for overseas expansion"],"answer":"reduced water consumption","explanation":"The paragraph focuses on reduced water consumption. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Water use fell after leaking pipes were repaired. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-19","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","what the fee includes"],"answer":"what the fee includes","explanation":"The paragraph focuses on what the fee includes. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The workshop fee covers materials but excludes lunch. This is the main u