insert into skill_lab_private.lessons(skill,module,version,content,published) values ('listening_distractors','listening',1,'{"skill":"listening_distractors","module":"listening","title":"Follow corrections","outcome":"Keep the final confirmed detail.","trap":"The first detail may be corrected later.","strategy":"Listen for correction signals such as actually, instead and sorry. Replace the earlier detail.","example":"Monday—sorry, Tuesday → Tuesday is the final answer.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"listening_distractors-0","kind":"choice","prompt":"On which day will the session take place?","options":["Tuesday","Thursday","No day is confirmed"],"answer":"Thursday","explanation":"The earlier day is corrected: the final arrangement is Thursday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for pottery. We first advertised Tuesday, but the session has moved to Thursday. The fee is 14 pounds, including materials. Please bring your studio.","audio":"/audio/skill-lab/listening_distractors-0.mp3","stage":"guided"},{"id":"listening_distractors-1","kind":"choice","prompt":"On which day will the session take place?","options":["Friday","No day is confirmed","Monday"],"answer":"Friday","explanation":"The earlier day is corrected: the final arrangement is Friday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for photography. We first advertised Monday, but the session has moved to Friday. The fee is 26 pounds, including materials. Please bring your camera.","audio":"/audio/skill-lab/listening_distractors-1.mp3","stage":"guided"},{"id":"listening_distractors-2","kind":"choice","prompt":"On which day will the session take place?","options":["No day is confirmed","Saturday","Sunday"],"answer":"Sunday","explanation":"The earlier day is corrected: the final arrangement is Sunday.","hint":"Compare every detail with the lesson strategy.","tr