insert into skill_lab_private.lessons(skill,module,version,content,published) values ('listening_answer_limits','listening',1,'{"skill":"listening_answer_limits","module":"listening","title":"Accurate short answers","outcome":"Record the requested detail within the word limit.","trap":"An extra word or wrong number can invalidate an answer.","strategy":"Read the instruction. Identify the answer type. Check spelling and the final number.","example":"Write ONE NUMBER: The charge is twenty pounds → 20.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"listening_answer_limits-0","kind":"short","prompt":"What is the fee in pounds? Write ONE NUMBER.","answer":"14","explanation":"The final fee is 14 pounds. The instruction asks for a number only.","hint":"Listen for the fee, not the day or the equipment.","transcript":"Here are the details for pottery. We first advertised Tuesday, but the session has moved to Thursday. The fee is 14 pounds, including materials. Please bring your studio.","audio":"/audio/skill-lab/listening_answer_limits-0.mp3","stage":"guided"},{"id":"listening_answer_limits-1","kind":"short","prompt":"What is the fee in pounds? Write ONE NUMBER.","answer":"26","explanation":"The final fee is 26 pounds. The instruction asks for a number only.","hint":"Listen for the fee, not the day or the equipment.","transcript":"Here are the details for photography. We first advertised Monday, but the session has moved to Friday. The fee is 26 pounds, including materials. Please bring your camera.","audio":"/audio/skill-lab/listening_answer_limits-1.mp3","stage":"guided"},{"id":"listening_answer_limits-2","kind":"short","prompt":"What is the fee in pounds? Write ONE NUMBER.","answer":"18","explanation":"The final fee is 18 pounds. The instruction asks for a number only.","hint":"Listen for the fee, not the day or the equipment.","transcript":"Here are the details for gardening. We first advertised Saturday, but the session has moved to S