insert into skill_lab_private.lessons(skill,module,version,content,published) values ('speaking_paraphrasing','speaking',1,'{"skill":"speaking_paraphrasing","module":"speaking","title":"Paraphrase naturally","outcome":"Explain an idea accurately using familiar language.","trap":"An impressive synonym can change the meaning.","strategy":"Keep the same claim and qualifiers. Explain an unfamiliar word simply instead of guessing.","example":"Equipment is available to borrow → you can use the equipment and return it later.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":"Practise paraphrase naturally. Describe a useful local service. Give a relevant reason and example.","items":[{"id":"speaking_paraphrasing-0","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["extended opening hours","the complete closure of the library","an increase in prices at the library"],"answer":"extended opening hours","explanation":"“extended opening hours” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six.","stage":"guided"},{"id":"speaking_paraphrasing-1","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the buses","an increase in prices at the buses","partial fleet replacement"],"answer":"partial fleet replacement","explanation":"“partial fleet replacement” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year.","stage":"guided"},{"id":"speaking_paraphrasing-2","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the museum","online booking availability","the complete closure of the museum"],"answer":"online booking availability","explanation":"“online booking availability” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online.","stage":"guided"},{"id":"speaking_paraphrasing-3","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["a fortnightly meeting","the complete closure of the garden","an increase in prices at the garden"],"answer":"a fortnightly meeting","explanation":"“a fortnightly meeting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday.","stage":"guided"},{"id":"speaking_paraphrasing-4","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the course","an increase in prices at the course","a six-week evening course"],"answer":"a six-week evening course","explanation":"“a six-week evening course” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May.","stage":"independent"},{"id":"speaking_paraphrasing-5","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the pool","a weekly maintenance closure","the complete closure of the pool"],"answer":"a weekly maintenance closure","explanation":"“a weekly maintenance closure” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning.","stage":"independent"},{"id":"speaking_paraphrasing-6","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["growth in cycle commuting","the complete closure of the bicycles","an increase in prices at the bicycles"],"answer":"growth in cycle commuting","explanation":"“growth in cycle commuting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"More residents cycled to work after a protected lane opened.","stage":"independent"},{"id":"speaking_paraphrasing-7","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the market","an increase in prices at the market","relocation after weather damage"],"answer":"relocation after weather damage","explanation":"“relocation after weather damage” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The market moved indoors because rain damaged the stalls.","stage":"independent"},{"id":"speaking_paraphrasing-8","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the cafe","local coffee purchasing","the complete closure of the cafe"],"answer":"local coffee purchasing","explanation":"“local coffee purchasing” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The cafe buys its coffee from two local suppliers.","stage":"independent"},{"id":"speaking_paraphrasing-9","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["more frequent trains","the complete closure of the trains","an increase in prices at the trains"],"answer":"more frequent trains","explanation":"“more frequent trains” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The new timetable reduced the wait between trains from fifteen to ten minutes.","stage":"independent"},{"id":"speaking_paraphrasing-10","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the school","an increase in prices at the school","a borrowing limit"],"answer":"a borrowing limit","explanation":"“a borrowing limit” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Students may borrow two books at a time.","stage":"independent"},{"id":"speaking_paraphrasing-11","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the park","a new lakeside path","the complete closure of the park"],"answer":"a new lakeside path","explanation":"“a new lakeside path” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The park has a new walking trail around the lake.","stage":"independent"},{"id":"speaking_paraphrasing-12","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["improved paper recycling","the complete closure of the recycling","an increase in prices at the recycling"],"answer":"improved paper recycling","explanation":"“improved paper recycling” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Households separated more paper after receiving labelled bins.","stage":"independent"},{"id":"speaking_paraphrasing-13","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the concert","an increase in prices at the concert","a ticket collection deadline"],"answer":"a ticket collection deadline","explanation":"“a ticket collection deadline” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Tickets must be collected before noon on Friday.","stage":"independent"},{"id":"speaking_paraphrasing-14","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the bakery","weekday opening times","the complete closure of the bakery"],"answer":"weekday opening times","explanation":"“weekday opening times” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The bakery opens at seven on weekdays.","stage":"independent"},{"id":"speaking_paraphrasing-15","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["less time commuting","the complete closure of the office","an increase in prices at the office"],"answer":"less time commuting","explanation":"“less time commuting” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Staff saved travel time by working from home twice a week.","stage":"independent"},{"id":"speaking_paraphrasing-16","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the tour","an increase in prices at the tour","a limited tour route"],"answer":"a limited tour route","explanation":"“a limited tour route” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The walking tour includes the castle but not the harbour.","stage":"independent"},{"id":"speaking_paraphrasing-17","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the clinic","two booking methods","the complete closure of the clinic"],"answer":"two booking methods","explanation":"“two booking methods” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Patients can request appointments by phone or through the website.","stage":"independent"},{"id":"speaking_paraphrasing-18","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["reduced water consumption","the complete closure of the water","an increase in prices at the water"],"answer":"reduced water consumption","explanation":"“reduced water consumption” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Water use fell after leaking pipes were repaired.","stage":"independent"},{"id":"speaking_paraphrasing-19","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the workshop","an increase in prices at the workshop","what the fee includes"],"answer":"what the fee includes","explanation":"“what the fee includes” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The workshop fee covers materials but excludes lunch.","stage":"independent"},{"id":"speaking_paraphrasing-20","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the station","a new waiting facility","the complete closure of the station"],"answer":"a new waiting facility","explanation":"“a new waiting facility” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"A waiting room was added beside platform two.","stage":"independent"},{"id":"speaking_paraphrasing-21","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["diversification of crops","the complete closure of the orchard","an increase in prices at the orchard"],"answer":"diversification of crops","explanation":"“diversification of crops” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Farmers planted more varieties to reduce dependence on one crop.","stage":"independent"},{"id":"speaking_paraphrasing-22","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the festival","an increase in prices at the festival","a revised festival date"],"answer":"a revised festival date","explanation":"“a revised festival date” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The festival takes place in September, not August as first announced.","stage":"independent"},{"id":"speaking_paraphrasing-23","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the gallery","an exhibition of regional art","the complete closure of the gallery"],"answer":"an exhibition of regional art","explanation":"“an exhibition of regional art” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The gallery displays paintings by regional artists.","stage":"independent"}]}'::jsonb,true) on conflict(skill,version) do nothing;
